def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    prev_high = 0.0
    prev_low_supply_pressure = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid > prev_high:
                    prev_high = bid
                ps = prev.get('supply')
                if ps is not None and float(ps) <= 18.0 and bid >= 90:
                    prev_low_supply_pressure += 1

    if not alive:
        return max(0.0, min(budget, 18.0))

    affordable_income = budget + DAILY_SALARY * max(0, 10 - day)
    tight_supply = supply <= 18.0
    very_tight = supply <= 16.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1
    if very_tight:
        urgency += 2
    elif tight_supply:
        urgency += 1

    if prev_bids:
        sorted_bids = sorted(prev_bids, reverse=True)
        top1 = sorted_bids[int(0)]
        top2 = sorted_bids[int(1)] if len(sorted_bids) > 1 else sorted_bids[int(0)]
    else:
        top1 = 80.0
        top2 = 70.0

    if urgency >= 5:
        target = max(top1 + 2.5, 118.0 if very_tight else 102.0)
    elif urgency >= 3:
        target = max(top2 + 1.5, 88.0 if tight_supply else 74.0)
    elif tight_supply:
        target = max(top2 + 1.0, 72.0)
    else:
        target = 34.0
        if prev_high >= 120.0:
            target = 28.0
        elif prev_high >= 90.0:
            target = 32.0

    if prev_low_supply_pressure >= 2 and tight_supply:
        target = max(target, top1 + 2.0)

    if budget < 90:
        if urgency >= 4:
            target = max(target, budget * 0.92)
        else:
            target = min(target, budget * 0.55)

    if affordable_income < 220 and urgency <= 2:
        target = min(target, 40.0)

    if day >= 8:
        if urgency >= 3:
            target = max(target, top2 + 2.0)
        else:
            target = max(target, 42.0)

    bid = min(budget, target)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if budget <= 0:
        return 0.0

    # React to yesterday's pressure using only previous_trace
    prev_bids = []
    prev_max_bid = None
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass
    if prev_bids:
        prev_max_bid = max(prev_bids)

    # Base target: if supply is near our requirement, competition is lower; if high supply, we can bid less.
    # Normalize supply to [0,1] where 15->0 and 25->1
    if MAX_SUPPLY > MIN_SUPPLY:
        s_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        s_norm = 0.5
    s_norm = max(0.0, min(1.0, float(s_norm)))

    # If my survival is at risk, bid harder.
    urgent = (hp <= 2) or (no_water_days >= 2)

    # Determine bid ceiling from budget and a fraction of daily salary.
    # Use yesterday max bid to decide whether the market is expensive.
    expensive_market = False
    if prev_max_bid is not None:
        if prev_max_bid >= DAILY_SALARY * 1.25:
            expensive_market = True

    # Choose a target bid
    if urgent:
        # High urgency: bid close to salary, but not exceed budget.
        if expensive_market:
            target = DAILY_SALARY * (0.95 - 0.10 * s_norm)
        else:
            target = DAILY_SALARY * (0.80 - 0.05 * s_norm)
    else:
        # Moderate urgency: bid around 55% of salary; reduce if supply is high.
        if expensive_market:
            # Still bid enough to beat the expensive crowd, but stay conservative.
            target = max(DAILY_SALARY * (0.60 - 0.10 * s_norm), (prev_max_bid * 0.65) if prev_max_bid is not None else DAILY_SALARY * 0.60)
        else:
            target = DAILY_SALARY * (0.52 - 0.08 * s_norm)

    # Additional tweak: if supply is very tight (near 15), increase slightly.
    if supply <= (MIN_SUPPLY + 1.0):
        target *= 1.10
    elif supply >= (MAX_SUPPLY - 1.0):
        target *= 0.90

    # Final cap to budget
    bid = min(float(budget), float(target))

    # Avoid returning negative/NaN
    if bid < 0:
        bid = 0.0

    return float(bid)

